-- The optimistic locking column (AuditableEntity.version) is NOT NULL in the DDL generated by
-- Hibernate 7.4 but nullable in V1 (generated with Hibernate 7.2). Rows inserted outside JPA may
-- hold NULL, so they are set to 0 before adding the constraint. Same type as in V1.

update anamnesis set version = 0 where version is null;
alter table anamnesis modify version integer not null;

update app_user set version = 0 where version is null;
alter table app_user modify version integer not null;

